//! `cfg_defines.h` -> `tt_isa::cfg::blackhole`.
//!
//! The file is machine-generated by Tenstorrent's `genCfgRegs.py`, so the format is
//! regular: every field has an `_ADDR32`, a `_SHAMT` and a `_MASK` define, and the
//! `// Registers for <SECTION>` comment above it decides whether the field lives in
//! `Config` (written with `WRCFG`) or `ThreadConfig` (written with `SETC16`). That
//! comment is why bindgen is the wrong tool here: it keeps the macros and drops the
//! section, which is the typing.
//!
//! `CFG_STATE_SIZE`, `THD_STATE_SIZE` and each `<SECTION>_CFGREG_BASE_ADDR32` are
//! carried too: they partition the `Config` space and size the banks.

use std::collections::BTreeMap;
use std::fmt::Write;

use crate::fetch;
use crate::pin;
use crate::util::{commit, rustfmt, workspace_root};

/// A pinned header and the file generated from it.
struct Header {
    /// The tt-metal revision the header is pinned at.
    rev: &'static str,
    /// The header's path inside tt-metal, for the generated file's doc.
    path: &'static str,
    /// The vendor copy of it.
    vendor: &'static str,
    /// Where the generated table goes.
    out: &'static str,
    /// Does this architecture's header describe `ThreadConfig`?
    thread_config: bool,
}

const BLACKHOLE: Header = Header {
    rev: pin::TT_METAL_REV,
    path: "tt_metal/hw/inc/blackhole/cfg_defines.h",
    vendor: "cfg_defines.h",
    out: "src/cfg/blackhole.rs",
    thread_config: true,
};

/// Quasar's header has no `ThreadConfig` at all: no `// Registers for THREAD`
/// section and no `THD_STATE_SIZE` (`tt-2xx/quasar/cfg_defines.h`).
const QUASAR: Header = Header {
    rev: pin::TT_METAL_QUASAR_REV,
    path: "tt_metal/hw/inc/internal/tt-2xx/quasar/cfg_defines.h",
    vendor: "cfg_defines_quasar.h",
    out: "src/cfg/quasar.rs",
    thread_config: false,
};

/// Regenerate `src/cfg/blackhole.rs`.
pub fn generate(check_only: bool) -> Result<(), String> {
    fetch::cfg_defines_if_needed()?;
    generate_from(&BLACKHOLE, check_only)
}

/// Regenerate `src/cfg/quasar.rs`.
pub fn generate_quasar(check_only: bool) -> Result<(), String> {
    fetch::quasar_cfg_defines_if_needed()?;
    generate_from(&QUASAR, check_only)
}

fn generate_from(header: &Header, check_only: bool) -> Result<(), String> {
    let file = workspace_root().join("vendor").join(header.vendor);
    let source =
        std::fs::read_to_string(&file).map_err(|e| format!("reading {}: {e}", file.display()))?;
    let table = parse(&source)?;
    let root = workspace_root();
    let rendered = rustfmt(&render(&table, header), &root)?;
    commit(&root.join(header.out), &rendered, check_only, header.vendor)
}

struct Field {
    name: String,
    section: String,
    addr32: u32,
    shamt: u32,
    /// Hex digits of the mask, unparsed: two fields carry 128-bit masks.
    mask: String,
}

struct Table {
    fields: Vec<Field>,
    cfg_state_size: u32,
    /// Absent on an architecture without `ThreadConfig` (Quasar).
    thd_state_size: Option<u32>,
    /// First `Config` word index of each section, from `<SECTION>_CFGREG_BASE_ADDR32`.
    bases: BTreeMap<String, u32>,
}

/// A field under construction: its section, then `ADDR32`, `SHAMT` and `MASK` as
/// each is encountered. The header emits them on consecutive lines, but nothing in
/// the format guarantees that, so they are collected independently.
type Partial = (String, Option<u32>, Option<u32>, Option<String>);

fn parse(source: &str) -> Result<Table, String> {
    let mut section = String::new();
    let mut parts: BTreeMap<String, Partial> = BTreeMap::new();
    let mut cfg_state_size = None;
    let mut thd_state_size = None;
    let mut bases = BTreeMap::new();

    for line in source.lines() {
        if let Some(rest) = line.strip_prefix("// Registers for ") {
            section = rest.trim().to_string();
            continue;
        }
        let Some(rest) = line.strip_prefix("#define ") else {
            continue;
        };
        let mut words = rest.split_whitespace();
        let (Some(name), Some(value)) = (words.next(), words.next()) else {
            continue;
        };
        match name {
            "CFG_STATE_SIZE" => {
                cfg_state_size = int(value);
                continue;
            }
            "THD_STATE_SIZE" => {
                thd_state_size = int(value);
                continue;
            }
            _ => {}
        }
        // `_RMW` expands to the other three; nothing to learn from it.
        let Some((stem, kind)) = name.rsplit_once('_') else {
            continue;
        };
        if !matches!(kind, "ADDR32" | "SHAMT" | "MASK") {
            continue;
        }
        // `<SECTION>_CFGREG_BASE_ADDR32` is the first word index of a section, not a
        // field: it has no SHAMT or MASK.
        if let Some(base_of) = stem.strip_suffix("_CFGREG_BASE") {
            if kind == "ADDR32" {
                if let Some(value) = int(value) {
                    bases.insert(base_of.to_string(), value);
                }
            }
            continue;
        }
        let entry = parts
            .entry(stem.to_string())
            .or_insert_with(|| (section.clone(), None, None, None));
        match kind {
            "ADDR32" => entry.1 = int(value),
            "SHAMT" => entry.2 = int(value),
            "MASK" => entry.3 = Some(value.to_string()),
            _ => unreachable!("filtered above"),
        }
    }

    let mut fields = Vec::new();
    for (name, (section, addr32, shamt, mask)) in parts {
        let (Some(addr32), Some(shamt), Some(mask)) = (addr32, shamt, mask) else {
            return Err(format!(
                "field `{name}` is missing one of ADDR32/SHAMT/MASK"
            ));
        };
        if section.is_empty() {
            return Err(format!("field `{name}` appears before any section header"));
        }
        if !bases.contains_key(&section) {
            return Err(format!("section `{section}` has no _CFGREG_BASE_ADDR32"));
        }
        // A mask wider than one word is a whole-register aggregate: all ones, shift
        // zero. Anything else is a parse bug, and a field that looks complete and is
        // not is precisely what this generator must not emit.
        let hex = mask.trim_start_matches("0x").trim_start_matches("0X");
        if hex.len() > 8 && (shamt != 0 || hex.chars().any(|c| c != 'f' && c != 'F')) {
            return Err(format!(
                "`{name}`: mask {mask} spans words but is not a whole-word run"
            ));
        }
        fields.push(Field {
            name,
            section,
            addr32,
            shamt,
            mask,
        });
    }
    if fields.is_empty() {
        return Err("parsed no fields; has the header format changed?".into());
    }
    Ok(Table {
        fields,
        cfg_state_size: cfg_state_size.ok_or("CFG_STATE_SIZE not found")?,
        thd_state_size,
        bases,
    })
}

fn int(s: &str) -> Option<u32> {
    let s = s.trim();
    match s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        Some(hex) => u32::from_str_radix(hex, 16).ok(),
        None => s.parse().ok(),
    }
}

fn render(table: &Table, header: &Header) -> String {
    let mut by_module: BTreeMap<String, Vec<&Field>> = BTreeMap::new();
    for f in &table.fields {
        by_module
            .entry(f.section.to_ascii_lowercase())
            .or_default()
            .push(f);
    }

    let mut out = String::new();
    writeln!(
        out,
        "//! Tensix backend-configuration fields, generated from `cfg_defines.h`.\n\
         //!\n\
         //! **Do not edit.** Regenerate with `cargo xtask gen-cfg`, which fetches the\n\
         //! pinned header itself; `cargo xtask gen-cfg --check` fails when this file is\n\
         //! out of date.\n\
         //!\n\
         //! Source: tt-metal `{}`, `{}`\n\
         //! ({} fields across {} sections).\n\
         //!\n\
         //! Field names are kept exactly as `cfg_defines.h` spells them, so that a name\n\
         //! in the specification can be searched for here without translation.\n\
         #![allow(non_upper_case_globals)]\n\
         #![allow(clippy::unreadable_literal)]\n\
         \n",
        header.rev,
        header.path,
        table.fields.len(),
        by_module.len(),
    )
    .unwrap();
    writeln!(
        out,
        "use super::{{ConfigField, ConfigSpan, ThreadConfigField}};\n"
    )
    .unwrap();
    writeln!(
        out,
        "/// `uint32_t Config[2][CFG_STATE_SIZE * 4]`\n\
         pub const CFG_STATE_SIZE: u32 = {};\n",
        table.cfg_state_size
    )
    .unwrap();
    if let Some(thd) = table.thd_state_size {
        writeln!(
            out,
            "/// `struct {{uint16_t Value, Padding;}} ThreadConfig[3][THD_STATE_SIZE]`\n\
             pub const THD_STATE_SIZE: u32 = {thd};\n"
        )
        .unwrap();
    }
    let _ = header;

    let mut config = Vec::new();
    let mut thread = Vec::new();
    let mut spans = Vec::new();
    let mut per_module: BTreeMap<String, Vec<(String, String)>> = BTreeMap::new();

    for (module, fields) in &by_module {
        let is_thread = fields[0].section == "THREAD";
        let section = &fields[0].section;
        let kind = if is_thread {
            "`ThreadConfig` (write with `SETC16`)"
        } else {
            "`Config` (write with `WRCFG`)"
        };
        writeln!(
            out,
            "/// `// Registers for {section}` — {} fields, indexing {kind}.\n\
             pub mod {module} {{\n    use super::*;\n\n    \
             /// First word index of this section, from `{section}_CFGREG_BASE_ADDR32`.\n    \
             pub const CFGREG_BASE: u16 = {};\n",
            fields.len(),
            table.bases[section]
        )
        .unwrap();

        for f in fields {
            let Field {
                name,
                addr32,
                shamt,
                mask,
                ..
            } = f;
            let hex = mask.trim_start_matches("0x").trim_start_matches("0X");
            if hex.len() > 8 {
                let words = (hex.len() / 8) as u32;
                writeln!(
                    out,
                    "    /// `Config[{addr32}..{}]` — a {}-bit aggregate, not a bitfield.\n    \
                     pub const {name}: ConfigSpan = ConfigSpan::new({addr32}, {words});",
                    addr32 + words,
                    words * 32
                )
                .unwrap();
                spans.push((module.clone(), name.clone()));
            } else if is_thread {
                writeln!(
                    out,
                    "    pub const {name}: ThreadConfigField = ThreadConfigField::new({addr32}, {shamt}, 0x{hex});"
                )
                .unwrap();
                thread.push((module.clone(), name.clone()));
            } else {
                writeln!(out, "    pub const {name}: ConfigField = ConfigField::new({addr32}, {shamt}, 0x{hex});")
                    .unwrap();
                config.push((module.clone(), name.clone()));
                per_module
                    .entry(module.clone())
                    .or_default()
                    .push((module.clone(), name.clone()));
            }
        }
        writeln!(out, "}}\n").unwrap();
    }

    // Flat tables, so invariants can be asserted over every field at once rather than
    // a sample, and per-section tables, because a field attributed to the wrong
    // section is still in bounds for `Config` as a whole.
    emit_table(&mut out, "ALL_CONFIG_FIELDS", "ConfigField", &config);
    emit_table(
        &mut out,
        "ALL_THREAD_CONFIG_FIELDS",
        "ThreadConfigField",
        &thread,
    );
    emit_table(&mut out, "ALL_CONFIG_SPANS", "ConfigSpan", &spans);
    for (module, items) in &per_module {
        emit_table(
            &mut out,
            &format!("{}_FIELDS", module.to_ascii_uppercase()),
            "ConfigField",
            items,
        );
    }
    out
}

fn emit_table(out: &mut String, name: &str, ty: &str, items: &[(String, String)]) {
    writeln!(out, "pub static {name}: &[(&str, {ty})] = &[").unwrap();
    for (module, field) in items {
        writeln!(out, "    (\"{field}\", {module}::{field}),").unwrap();
    }
    writeln!(out, "];\n").unwrap();
}
